use strict; use warnings;
my %seq; my $n; while(<>) { chomp; if(/^>(\S+)/){$n=$1} else {$seq{$n}.=$_} }
my $s=$seq{input};
my $pos=213; my $diff=39; my $insert=substr($seq{output},$pos,$diff);
