my $check_right=substr($s,$right_start,length($right_anneal));
print "check_left $check_left\ncheck_right $check_right\n";
# Build primers (Q5 SDM): forward = left_anneal + insert + right_anneal
my $forward = $left_anneal . $insert . $right_anneal;
print "forward len ",length($forward),"\n";
# reverse primer = reverse complement of forward
my $revcomp = reverse($forward); $revcomp =~ tr/acgtACGT/tgcaTGCA/;
print "revcomp len ",length($revcomp),"\n";
print "forward\n$forward\nreverse\n$revcomp\n";
PERL"}

